CREATE TABLE IF NOT EXISTS match_homologation_versions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,match_id BIGINT UNSIGNED NOT NULL,version_number INT UNSIGNED NOT NULL,snapshot_json JSON NOT NULL,integrity_hash CHAR(64) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'homologated',pdf_path VARCHAR(255) NULL,created_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,UNIQUE KEY match_version(match_id,version_number),FOREIGN KEY(match_id) REFERENCES matches(id),FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS rectification_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,match_id BIGINT UNSIGNED NOT NULL,current_version_id BIGINT UNSIGNED NULL,requested_by BIGINT UNSIGNED NULL,reason TEXT NOT NULL,questioned_fields_json JSON NULL,status VARCHAR(30) NOT NULL DEFAULT 'requested',decision_note TEXT NULL,decided_by BIGINT UNSIGNED NULL,decided_at DATETIME NULL,applied_at DATETIME NULL,impact_json JSON NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,INDEX rectification_match_status(match_id,status),FOREIGN KEY(match_id) REFERENCES matches(id),FOREIGN KEY(current_version_id) REFERENCES match_homologation_versions(id),FOREIGN KEY(requested_by) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(decided_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
